const pick = <T extends Record<string, L>>(table: T, ref: keyof T | L): L => (Array.isArray(ref) ? (ref as L) : table[ref as keyof T]);
/** Deriva numerador y denominador de una fórmula «A / B × 100». */
function sides(formula: string, id: string): [string, string] {
  const m = /^(.*?) \/ (.*?) × 100(?=[,;]|$)/.exec(formula);
  if (!m) throw new Error(`kpi.${id}: no se pueden derivar numerador y denominador de «${formula}»`);
  const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
  return [cap(m[1]), cap(m[2])];
}

const bundle: Bundle = { es: {}, en: {}, pt: {} };
(['es', 'en', 'pt'] as const).forEach((lang, i) => {
  for (const [id, r] of Object.entries(ROWS)) {
    const auto = r.num && r.den ? null : sides(r.f[i], id);
    const text: Record<(typeof KPI_TEXT_FIELDS)[number], string> = {
      name: r.n[i], short: r.s[i], purpose: r.p[i], formula: r.f[i],
      numerator: r.num ? r.num[i] : auto![0], denominator: r.den ? r.den[i] : auto![1], exclusions: r.x[i],
      source: pick(SRC, r.src)[i], periodicity: pick(PER, r.per)[i], owner: OWNER[r.o][i], target: pick(TG, r.tg)[i], missing: pick(MI, r.mi)[i],
    };
    for (const field of KPI_TEXT_FIELDS) bundle[lang][`kpi.${id}.${field}`] = text[field];
  }
});
registerDict(bundle);

/** Ids del catálogo (KPI_IDS) que no tienen ficha de textos: debe quedar vacío. */
export const KPI_TEXT_MISSING: string[] = KPI_IDS.filter((id) => !(id in ROWS));
